let deck = game.cards.find(c => c.system.fq.type === 'DECK' && c.ownership[game.userId] === 3)
let spellBook = game.cards.find(c => c.system.fq.type === 'SPELLBOOK' && c.ownership[game.userId] === 3)
let hand = game.cards.find(c => c.system.fq.type === 'HAND' && c.ownership[game.userId] === 3)
let pile = game.cards.find(c => c.system.fq.type === 'PILE' && c.ownership[game.userId] === 3)

if ( !deck || !hand || !pile  ) {
  socket = socketlib.registerModule(FqCardEngineModule.moduleName);
  await socket.executeAsGM('createDeckForUser', game.userId);
}

deck = game.cards.find(c => c.system.fq.type === 'DECK' && c.ownership[game.userId] === 3)

spellBook = game.cards.find(c => c.system.fq.type === 'SPELLBOOK' && c.ownership[game.userId] === 3)

if (deck) {
  deck.sheet.render(true, {
        left: 110,
        top: 100
  });
}

if (spellBook) {
    spellBook.sheet.render(true, {
        left: 110 + deck.sheet.position.width,
        top: 100
    });
}
